35: // Browser is the high-level Chrome DevTools Protocol browser manager, handling
36: // the browser process runner, WebSocket clients, associated targets, and
37: // network, page, and DOM events.
38: type Browser struct {
39: 	// next is the next message id.
40: 	// NOTE: needs to be 64-bit aligned for 32-bit targets too, so be careful when moving this field.
41: 	// This will be eventually done by the compiler once https://github.com/golang/go/issues/599 is fixed.
42: 	next int64
43: 
44: 	// LostConnection is closed when the websocket connection to Chrome is
45: 	// dropped. This can be useful to make sure that Browser's context is
46: 	// cancelled (and the handler stopped) once the connection has failed.
47: 	LostConnection chan struct{}
48: 
49: 	// closingGracefully is closed by Close before gracefully shutting down
50: 	// the browser. This way, when the connection to the browser is lost and
51: 	// LostConnection is closed, we will know not to immediately kill the
52: 	// Chrome process. This is important to let the browser shut itself off,
53: 	// saving its state to disk.
54: 	closingGracefully chan struct{}
55: 
56: 	dialTimeout time.Duration
57: 
58: 	// pages keeps track of the attached targets, indexed by each's session
59: 	// ID. The only reason this is a field is so that the tests can check the
60: 	// map once a browser is closed.
61: 	pages map[target.SessionID]*Target
62: 
63: 	listenersMu sync.Mutex
64: 	listeners   []cancelableListener
65: 
66: 	conn Transport
67: 
68: 	// newTabQueue is the queue used to create new target handlers, once a new
69: 	// tab is created and attached to. The newly created Target is sent back
70: 	// via newTabResult.
71: 	newTabQueue chan *Target
72: 
73: 	// cmdQueue is the outgoing command queue.
74: 	cmdQueue chan *cdproto.Message
75: 
76: 	// logging funcs
77: 	logf func(string, ...any)
78: 	errf func(string, ...any)
79: 	dbgf func(string, ...any)
80: 
81: 	// The optional fields below are helpful for some tests.
82: 
83: 	// process can be initialized by the allocators which start a process
84: 	// when allocating a browser.
85: 	process *os.Process
86: 
87: 	// userDataDir can be initialized by the allocators which set up user
88: 	// data dirs directly.
89: 	userDataDir string
90: }
91: 
92: // NewBrowser creates a new browser. Typically, this function wouldn't be called
93: // directly, as the Allocator interface takes care of it.
94: func NewBrowser(ctx context.Context, urlstr string, opts ...BrowserOption) (*Browser, error) {
95: 	b := &Browser{
96: 		LostConnection:    make(chan struct{}),
97: 		closingGracefully: make(chan struct{}),
98: 
99: 		dialTimeout: 10 * time.Second,
100: 
101: 		newTabQueue: make(chan *Target),
102: 
103: 		// Fit some jobs without blocking, to reduce blocking in Execute.
104: 		cmdQueue: make(chan *cdproto.Message, 32),
105: 
106: 		logf: log.Printf,
107: 	}
108: 	// apply options
109: 	for _, o := range opts {
110: 		o(b)
111: 	}
112: 	// ensure errf is set
113: 	if b.errf == nil {
114: 		b.errf = func(s string, v ...any) { b.logf("ERROR: "+s, v...) }
115: 	}
116: 
117: 	dialCtx := ctx
118: 	if b.dialTimeout > 0 {
119: 		var cancel context.CancelFunc
120: 		dialCtx, cancel = context.WithTimeout(ctx, b.dialTimeout)
121: 		defer cancel()
122: 	}
123: 
124: 	var err error
125: 	b.conn, err = DialContext(dialCtx, urlstr, WithConnDebugf(b.dbgf))
126: 	if err != nil {
127: 		return nil, fmt.Errorf("could not dial %q: %w", urlstr, err)
128: 	}
129: 
130: 	go b.run(ctx)
131: 	return b, nil
132: }
133: 
134: // Process returns the process object of the browser.
135: //
136: // It could be nil when the browser is allocated with RemoteAllocator.
137: // It could be useful for a monitoring system to collect process metrics of the browser process.
138: // (See [prometheus.NewProcessCollector] for an example).
139: //
140: // Example:
141: //
142: //	if process := chromedp.FromContext(ctx).Browser.Process(); process != nil {
143: //		fmt.Printf("Browser PID: %v", process.Pid)
144: //	}
145: //
146: // [prometheus.NewProcessCollector]: https://pkg.go.dev/github.com/prometheus/client_golang/prometheus#NewProcessCollector
147: func (b *Browser) Process() *os.Process {
148: 	return b.process
149: }
