151: func (b *Browser) newExecutorForTarget(ctx context.Context, targetID target.ID, sessionID target.SessionID) (*Target, error) {
152: 	if targetID == "" {
153: 		return nil, errors.New("empty target ID")
154: 	}
155: 	if sessionID == "" {
156: 		return nil, errors.New("empty session ID")
157: 	}
158: 	t := &Target{
159: 		browser:   b,
160: 		TargetID:  targetID,
161: 		SessionID: sessionID,
162: 
163: 		messageQueue: make(chan *cdproto.Message, 1024),
164: 		frames:       make(map[cdp.FrameID]*cdp.Frame),
165: 		execContexts: make(map[cdp.FrameID]runtime.ExecutionContextID),
166: 		cur:          cdp.FrameID(targetID),
167: 
168: 		logf: b.logf,
169: 		errf: b.errf,
170: 	}
171: 
172: 	// This send should be blocking, to ensure the tab is inserted into the
173: 	// map before any more target events are routed.
174: 	select {
175: 	case <-ctx.Done():
176: 		return nil, ctx.Err()
177: 	case b.newTabQueue <- t:
178: 	}
179: 	return t, nil
180: }
181: 
182: func (b *Browser) Execute(ctx context.Context, method string, params, res any) error {
183: 	// Certain methods aren't available to the user directly.
184: 	if method == browser.CommandClose {
185: 		return fmt.Errorf("to close the browser gracefully, use chromedp.Cancel")
186: 	}
187: 	return b.execute(ctx, method, params, res)
188: }
189: 
190: func (b *Browser) execute(ctx context.Context, method string, params, res any) error {
191: 	id := atomic.AddInt64(&b.next, 1)
192: 	lctx, cancel := context.WithCancel(ctx)
193: 	ch := make(chan *cdproto.Message, 1)
194: 	fn := func(ev any) {
195: 		if msg, ok := ev.(*cdproto.Message); ok && msg.ID == id {
196: 			select {
197: 			case <-ctx.Done():
198: 			case ch <- msg:
199: 			}
200: 			cancel()
201: 		}
202: 	}
203: 	b.listenersMu.Lock()
204: 	b.listeners = append(b.listeners, cancelableListener{lctx, fn})
205: 	b.listenersMu.Unlock()
206: 
207: 	// send command
208: 	var buf []byte
209: 	if params != nil {
210: 		var err error
211: 		if buf, err = jsonv2.Marshal(params, DefaultMarshalOptions); err != nil {
212: 			return err
213: 		}
214: 	}
215: 	cmd := &cdproto.Message{
216: 		ID:     id,
217: 		Method: cdproto.MethodType(method),
218: 		Params: buf,
219: 	}
220: 	select {
221: 	case <-ctx.Done():
222: 		return ctx.Err()
223: 	case b.cmdQueue <- cmd:
224: 	}
225: 
226: 	// wait for result
227: 	select {
228: 	case <-ctx.Done():
229: 		return ctx.Err()
230: 	case msg := <-ch:
231: 		switch {
232: 		case msg == nil:
233: 			return ErrChannelClosed
234: 		case msg.Error != nil:
235: 			return msg.Error
236: 		case res != nil:
237: 			return jsonv2.Unmarshal(msg.Result, res, DefaultUnmarshalOptions)
238: 		}
239: 	}
240: 	return nil
241: }
242: 
243: func (b *Browser) run(ctx context.Context) {
244: 	defer b.conn.Close()
245: 
246: 	// incomingQueue is the queue of incoming target events, to be routed by
247: 	// their session ID.
248: 	incomingQueue := make(chan *cdproto.Message, 1)
249: 
250: 	delTabQueue := make(chan target.SessionID, 1)
251: 
252: 	// This goroutine continuously reads events from the websocket
253: 	// connection. The separate goroutine is needed since a websocket read
254: 	// is blocking, so it cannot be used in a select statement.
255: 	go func() {
256: 		// Signal to run and exit the browser cleanup goroutine.
257: 		defer close(b.LostConnection)
258: 
259: 		for {
260: 			msg := new(cdproto.Message)
261: 			if err := b.conn.Read(ctx, msg); err != nil {
262: 				var syntacticError *jsontext.SyntacticError
263: 				if errors.As(err, &syntacticError) {
264: 					b.errf("%s", err)
265: 				}
266: 				return
267: 			}
268: 
269: 			switch {
270: 			case msg.SessionID != "" && (msg.Method != "" || msg.ID != 0):
271: 				select {
272: 				case <-ctx.Done():
273: 					return
274: 				case incomingQueue <- msg:
275: 				}
276: 
277: 			case msg.Method != "":
278: 				ev, err := cdproto.UnmarshalMessage(msg, DefaultUnmarshalOptions)
279: 				if err != nil {
280: 					b.errf("%s", err)
281: 					continue
282: 				}
283: 				b.listenersMu.Lock()
284: 				b.listeners = runListeners(b.listeners, ev)
285: 				b.listenersMu.Unlock()
286: 
287: 				if ev, ok := ev.(*target.EventDetachedFromTarget); ok {
288: 					delTabQueue <- ev.SessionID
289: 				}
290: 
291: 			case msg.ID != 0:
292: 				b.listenersMu.Lock()
293: 				b.listeners = runListeners(b.listeners, msg)
294: 				b.listenersMu.Unlock()
295: 
296: 			default:
297: 				b.errf("ignoring malformed incoming message (missing id or method): %#v", msg)
298: 			}
299: 		}
300: 	}()
301: 
302: 	b.pages = make(map[target.SessionID]*Target, 32)
303: 	for {
304: 		select {
305: 		case <-ctx.Done():
306: 			return
307: 
308: 		case msg := <-b.cmdQueue:
309: 			if err := b.conn.Write(ctx, msg); err != nil {
310: 				b.errf("%s", err)
311: 				continue
312: 			}
313: 
314: 		case t := <-b.newTabQueue:
315: 			if _, ok := b.pages[t.SessionID]; ok {
316: 				b.errf("executor for %q already exists", t.SessionID)
317: 			}
318: 			b.pages[t.SessionID] = t
319: 
320: 		case sessionID := <-delTabQueue:
321: 			if _, ok := b.pages[sessionID]; !ok {
322: 				b.errf("executor for %q doesn't exist", sessionID)
323: 			}
324: 			delete(b.pages, sessionID)
325: 
326: 		case m := <-incomingQueue:
327: 			page, ok := b.pages[m.SessionID]
328: 			if !ok {
329: 				// A page we recently closed still sending events.
330: 				continue
331: 			}
332: 
333: 			select {
334: 			case <-ctx.Done():
335: 				return
336: 			case page.messageQueue <- m:
337: 			}
338: 
339: 		case <-b.LostConnection:
340: 			return // to avoid "write: broken pipe" errors
341: 		}
342: 	}
343: }
