345: // BrowserOption is a browser option.
346: type BrowserOption = func(*Browser)
347: 
348: // WithBrowserLogf is a browser option to specify a func to receive general logging.
349: func WithBrowserLogf(f func(string, ...any)) BrowserOption {
350: 	return func(b *Browser) { b.logf = f }
351: }
352: 
353: // WithBrowserErrorf is a browser option to specify a func to receive error logging.
354: func WithBrowserErrorf(f func(string, ...any)) BrowserOption {
355: 	return func(b *Browser) { b.errf = f }
356: }
357: 
358: // WithBrowserDebugf is a browser option to specify a func to log actual
359: // websocket messages.
360: func WithBrowserDebugf(f func(string, ...any)) BrowserOption {
361: 	return func(b *Browser) { b.dbgf = f }
362: }
363: 
364: // WithConsolef is a browser option to specify a func to receive chrome log events.
365: //
366: // Note: NOT YET IMPLEMENTED.
367: func WithConsolef(f func(string, ...any)) BrowserOption {
368: 	return func(b *Browser) {}
369: }
