17: // forceIP tries to force the host component in urlstr to be an IP address.
18: //
19: // Since Chrome 66+, Chrome DevTools Protocol clients connecting to a browser
20: // must send the "Host:" header as either an IP address, or "localhost".
21: // See https://github.com/chromium/chromium/commit/0e914b95f7cae6e8238e4e9075f248f801c686e6.
22: func forceIP(ctx context.Context, urlstr string) (string, error) {
23: 	u, err := url.Parse(urlstr)
24: 	if err != nil {
25: 		return "", err
26: 	}
27: 	host, port, err := net.SplitHostPort(u.Host)
28: 	if err != nil {
29: 		return "", err
30: 	}
31: 	host, err = resolveHost(ctx, host)
32: 	if err != nil {
33: 		return "", err
34: 	}
35: 	u.Host = net.JoinHostPort(host, port)
36: 	return u.String(), nil
37: }
