39: // resolveHost tries to resolve a host to be an IP address. If the host is
40: // an IP address or "localhost", it returns the host directly.
41: func resolveHost(ctx context.Context, host string) (string, error) {
42: 	if host == "localhost" {
43: 		return host, nil
44: 	}
45: 	ip := net.ParseIP(host)
46: 	if ip != nil {
47: 		return host, nil
48: 	}
49: 
50: 	addrs, err := net.DefaultResolver.LookupIPAddr(ctx, host)
51: 	if err != nil {
52: 		return "", err
53: 	}
54: 
55: 	return addrs[0].IP.String(), nil
56: }
