58: // modifyURL modifies the websocket debugger URL if the provided URL is not a
59: // valid websocket debugger URL.
60: //
61: // A websocket debugger URL containing "/devtools/browser/" are considered
62: // valid. In this case, urlstr will only be modified by forceIP.
63: //
64: // Otherwise, it will construct a URL like http://[host]:[port]/json/version
65: // and query the valid websocket debugger URL from this endpoint. The [host]
66: // and [port] are parsed from the urlstr. If the host component is not an IP,
67: // it will be resolved to an IP first. Example parameters:
68: //   - ws://127.0.0.1:9222/
69: //   - http://127.0.0.1:9222/
70: //   - http://container-name:9222/
71: func modifyURL(ctx context.Context, urlstr string) (string, error) {
72: 	lctx, cancel := context.WithTimeout(ctx, 20*time.Second)
73: 	defer cancel()
74: 
75: 	if strings.Contains(urlstr, "/devtools/browser/") {
76: 		return forceIP(lctx, urlstr)
77: 	}
78: 
79: 	// replace the scheme and path to construct a URL like:
80: 	// http://127.0.0.1:9222/json/version
81: 	u, err := url.Parse(urlstr)
82: 	if err != nil {
83: 		return "", err
84: 	}
85: 	u.Scheme = "http"
86: 	host, port, err := net.SplitHostPort(u.Host)
87: 	if err != nil {
88: 		return "", err
89: 	}
90: 	host, err = resolveHost(ctx, host)
91: 	if err != nil {
92: 		return "", err
93: 	}
94: 	u.Host = net.JoinHostPort(host, port)
95: 	u.Path = "/json/version"
96: 
97: 	// to get "webSocketDebuggerUrl" in the response
98: 	req, err := http.NewRequestWithContext(lctx, "GET", u.String(), nil)
99: 	if err != nil {
100: 		return "", err
101: 	}
102: 	resp, err := http.DefaultClient.Do(req)
103: 	if err != nil {
104: 		return "", err
105: 	}
106: 	defer resp.Body.Close()
107: 
108: 	var result map[string]any
109: 	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
110: 		return "", err
111: 	}
112: 	// the browser will construct the debugger URL using the "host" header of
113: 	// the /json/version request. For example, run headless-shell in a container:
114: 	//     docker run -d -p 9000:9222 chromedp/headless-shell:latest
115: 	// then:
116: 	//     curl http://127.0.0.1:9000/json/version
117: 	// and the websocket debugger URL will be something like:
118: 	// ws://127.0.0.1:9000/devtools/browser/...
119: 	wsURL := result["webSocketDebuggerUrl"].(string)
120: 	return wsURL, nil
121: }
